save('sdks/rust/src/lib.rs','''//! Generated by scripts/generate-sdk-transports.py. Credentials remain in relay-broker storage.
use serde_json::{Value,json};
use std::{io::Write,process::{Command,Stdio}};
pub struct Client {pub broker:String,pub profile:String,pub directory:Option<String>,pub relay_url:Option<String>,pub storage_command:Option<String>}
impl Default for Client{fn default()->Self{Self{broker:"relay-broker".into(),profile:"default".into(),directory:None,relay_url:None,storage_command:None}}}
impl Client {
 pub fn invoke(&self,operation:&str,input:Value,connection_id:Option<&str>)->Result<Value,Box<dyn std::error::Error>>{
 let mut child=Command::new(&self.broker).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::null()).spawn()?;
 let payload=json!({"operation":operation,"input":if input.is_null(){json!({})}else{input},"connectionId":connection_id,"profile":self.profile,"directory":self.directory,"relayUrl":self.relay_url,"storageCommand":self.storage_command});
 child.stdin.take().ok_or("broker input unavailable")?.write_all(&serde_json::to_vec(&payload)?)?;
 let output=child.wait_with_output()?;let result:Value=serde_json::from_slice(&output.stdout)?;
 if result["ok"]!=true{return Err(result["error"].as_str().unwrap_or("relay operation failed").to_owned().into());}Ok(result["value"].clone())
 }
'''+''.join(f' pub fn {snake(op)}(&self,input:Value,connection_id:Option<&str>)->Result<Value,Box<dyn std::error::Error>>{{self.invoke("{op}",input,connection_id)}}\n' for op in operations)+'}\n')
